{"description":"Prepare page extraction and OCR scripts","code":"const ex=`import json
import os
import sys
import fitz

source = sys.argv[1]
out_dir = sys.argv[2]
os.makedirs(out_dir, exist_ok=True)
doc = fitz.open(source)
manifest = []
for index, page in enumerate(doc):
    images = page.get_images(full=True)
    if not images:
        raise RuntimeError(f"page {index + 1} has no image")
    xref = images[0][0]
    info = doc.extract_image(xref)
    ext = info["ext"]
    image_path = os.path.join(out_dir, f"page-{index + 1:04d}.{ext}")
    with open(image_path, "wb") as handle:
        handle.write(info["image"])
    rects = page.get_image_rects(xref)
    rect = rects[0] if rects else page.rect
    manifest.append({
        "page": index + 1,
        "path": image_path,
        "xref": xref,
        "width": info["width"],
        "height": info["height"],
        "ext": ext,
        "page_rect": [page.rect.x0, page.rect.y0, page.rect.x1, page.rect.y1],
        "image_rect": [rect.x0, rect.y0, rect.x1, rect.y1],
    })
with open(os.path.join(out_dir, "manifest.json"), "w", encoding="utf-8") as handle:
    json.dump({"source": source, "pages": manifest}, handle, ensure_ascii=False, indent=2)
print(json.dumps({"pages": len(manifest), "out_dir": out_dir}, ensure_ascii=False))
`;
const swift=`import Foundation
import Vision
import CoreGraphics
import ImageIO

struct OCRItem: Codable {
    let text: String
    let confidence: Float
    let x: Double
    let y: Double
    let width: Double
    let height: Double
}

func loadImage(_ url: URL) -> CGImage? {
    guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return nil }
    return CGImageSourceCreateImageAtIndex(source, 0, nil)
}

let inputDir = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
let outputDir = URL(fileURLWithPath: CommandLine.arguments[2], isDirectory: true)
try FileManager.default.createDirectory(at: outputDir, withIntermediateDirectories: true)
let files = try FileManager.default.contentsOfDirectory(at: inputDir, includingPropertiesForKeys: nil)
    .filter { $0.pathExtension.lowercased() == "jpg" || $0.pathExtension.lowercased() == "jpeg" }
    .sorted { $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent) == .orderedAscending }

for (index, url) in files.enumerated() {
    autoreleasepool {
        guard let image = loadImage(url) else {
            fputs("cannot read \\(url.path)\\n", stderr)
            return
        }
        let request = VNRecognizeTextRequest()
        request.recognitionLevel = .accurate
        request.recognitionLanguages = ["zh-Hans", "en-US"]
        request.usesLanguageCorrection = true
        request.minimumTextHeight = 0.003
        let handler = VNImageRequestHandler(cgImage: image, options: [:])
        do {
            try handler.perform([request])
        } catch {
            fputs("OCR failed for \\(url.lastPathComponent): \\(error)\\n", stderr)
            return
        }
        let items = (request.results ?? []).compactMap { observation -> OCRItem? in
            guard let candidate = observation.topCandidates(1).first else { return nil }
            let box = observation.boundingBox
            return OCRItem(text: candidate.string, confidence: candidate.confidence, x: box.origin.x, y: box.origin.y, width: box.width, height: box.height)
        }
        do {
            let data = try JSONEncoder().encode(items)
            let name = url.deletingPathExtension().lastPathComponent + ".json"
            try data.write(to: outputDir.appendingPathComponent(name))
        } catch {
            fputs("write failed for \\(url.lastPathComponent): \\(error)\\n", stderr)
        }
        if (index + 1) % 10 == 0 || index + 1 == files.count {
            print("OCR \\(index + 1)/\\(files.count)", flush: true)
        }
    }
}
`;
