{"description":"Create detailed PDF outline builder","code":"const content=`import difflib
import json
import re
from pathlib import Path

import fitz

SOURCE = "计算机网络（第8版） (谢希仁).pdf"
OCR_DIR = Path(".work/pages/ocr")
OUTPUT = Path(".work/outline.json")


def normalize_text(text):
    text = str(text).replace("|", "").replace("．", ".")
    text = re.sub(r"[.…⋯，,。；;：:]+$", "", text)
    text = re.sub(r"\\s+", "", text)
    return text.strip()


def clean_title(text):
    text = re.sub(r"[.…⋯，,。；;：:]+$", "", text)
    text = text.replace("|", "")
    text = re.sub(r"\\s+", " ", text).strip()
    return text


def group_body_lines():
    pages = {}
    for page in range(12, 486):
        source = OCR_DIR / f"page-{page:04d}.json"
        if not source.exists():
            continue
        items = json.loads(source.read_text(encoding="utf-8"))
        items.sort(key=lambda item: (-float(item.get("y", 0)), float(item.get("x", 0))))
        rows = []
        for item in items:
            text = str(item.get("text", "")).strip()
            if not text:
                continue
            y = float(item.get("y", 0))
            if rows and abs(y - rows[-1]["y"]) <= 0.004:
                rows[-1]["items"].append(item)
            else:
                rows.append({"y": y, "items": [item]})
        result = []
        for row in rows:
            row["items"].sort(key=lambda item: float(item.get("x", 0)))
            text = " ".join(str(item.get("text", "")).strip() for item in row["items"])
            result.append({"text": text, "norm": normalize_text(text), "y": row["y"]})
        pages[page] = result
    return pages


def parse_section(text):
    compact = text.replace("|", "")
    match = re.match(r"^\\s*(\\d+)\\s*\\.\\s*(\\d+)(?:\\s*\\.\\s*(\\d+))?\\s+(.+)$", compact)
    if not match:
        return None
    code = match.group(1) + "." + match.group(2)
    if match.group(3):
        code += "." + match.group(3)
    if int(match.group(1)) not in range(1, 10):
        return None
    title = clean_title(match.group(4))
    if len(title) < 2:
        return None
    return code, title


def find_section_page(code, title, body_pages, start_page, end_page):
    code_norm = normalize_text(code)
    title_norm = normalize_text(title)
    title_chars = re.sub(r"[^0-9A-Za-z\\u4e00-\\u9fff]", "", title_norm)
    prefixes = []
    if len(title_chars) >= 6:
        prefixes.append(title_chars[:6])
    if len(title_chars) >= 4:
        prefixes.append(title_chars[:4])
    candidates = []
    for page in range(start_page, end_page + 1):
        for row in body_pages.get(page, []):
            norm = row["norm"]
            if not norm.startswith(code_norm):
                continue
            score = 0
            if title_norm and title_norm in norm:
                score += 100
            for prefix in prefixes:
                if prefix in norm:
                    score += len(prefix)
                    break
            if score:
                candidates.append((page, score, row["text"]))
    if candidates:
        candidates.sort(key=lambda value: (-value[1], value[0]))
        return candidates[0][0], candidates[0][2]
    return None, None


def find_special(phrase, body_pages, start_page, end_page):
    phrase_norm = normalize_text(phrase)
    matches = []
    for page in range(start_page, end_page + 1):
        for row in body_pages.get(page, []):
            if phrase_norm in row["norm"] and len(row["norm"]) <= len(phrase_norm) + 12:
                matches.append((page, row["text"]))
    return matches[-1] if matches else (None, None)


source = fitz.open(SOURCE)
existing = source.get_toc()
chapter_pages = {}
appendix_pages = {}
for level, title, page, *rest in existing:
    chapter = re.search(r"第\\s*(\\d+)\\s*章", title)
    appendix = re.search(r"附录\\s*([A-C])", title)
    if chapter:
        chapter_pages[int(chapter.group(1))] = page
    if appendix:
        appendix_pages[appendix.group(1)] = page

body_pages = group_body_lines()
rows = json.loads(Path(".work/toc-rows.json").read_text(encoding="utf-8"))
outline = []
current_chapter = None
unresolved = []
seen_codes = set()
for row in rows:
    text = clean_title(row["text"])
    if text in {"目 录", "• VI•", "•VIII•", "•X•"}:
        continue
    chapter = re.match(r"^第\\s*(\\d+)\\s*章\\s*(.*)$", text)
    appendix = re.match(r"^附录\\s*([A-C])\\s*(.*)$", text)
    section = parse_section(text)
    if chapter:
        number = int(chapter.group(1))
        current_chapter = number
        page = chapter_pages.get(number)
        if page:
            outline.append([1, text, page])
        else:
            unresolved.append({"text": text, "reason": "chapter page missing"})
        continue
    if appendix:
        current_chapter = None
        key = appendix.group(1)
        page = appendix_pages.get(key)
        if page:
            outline.append([1, text, page])
        else:
            unresolved.append({"text": text, "reason": "appendix page missing"})
        continue
    if section and current_chapter is not None:
        code, title = section
        if code in seen_codes:
            continue
        seen_codes.add(code)
        start = chapter_pages.get(current_chapter, 12)
        next_page = min((page for number, page in chapter_pages.items() if number > current_chapter), default=485) - 1
        page, matched = find_section_page(code, title, body_pages, start, max(start, next_page))
        if page is None:
            unresolved.append({"text": f"{code} {title}", "reason": "section heading not found"})
            continue
        level = 2 if code.count(".") == 1 else 3
        outline.append([level, f"{code} {title}", page])
        continue
    if current_chapter is not None and text in {"本章的重要概念", "习题"}:
        start = chapter_pages.get(current_chapter, 12)
        next_page = min((page for number, page in chapter_pages.items() if number > current_chapter), default=485) - 1
        page, matched = find_special(text, body_pages, start, max(start, next_page))
        if page is not None:
            outline.append([2, text, page])
        else:
            unresolved.append({"text": text, "reason": "special section not found"})

# 保留原有的前置条目（封面、前言、目录等），再接入详细章节目录。
intro = []
for entry in existing:
    title = entry[1]
    if re.search(r"第\\s*\\d+\\s*章", title) or re.search(r"附录\\s*[A-C]", title):
        break
    intro.append(entry[:3])
